/// <summary>
/// The write side: product receipts, transfer shipments and transfer receipts.
///
/// **Landing and processing are two different steps, on purpose.** postProductReceipt and
/// postTransfer used to do the real work inline - resolving InventTrans, walking InventDim,
/// running the transfer engine - in the same request the operator's device was blocked on.
/// Confirmed live against this tenant that the real work can take upwards of a minute under
/// load; an operator standing at a scanner should never wait that out. Both methods now do one
/// thing only - validate the shape, check idempotency, insert a HSMobileOpsPostQueue row, return
/// - and are back in well under a second regardless of how slow the real work would have been.
/// The real work happens in processWarehouse - one batch task per warehouse, started every few
/// minutes by the recurring job HSMobileOpsProcessPendingBatch - and in processCompany, at once
/// from the Activity screen's "Process pending" action (processPending), for small postings only.
/// Either way it is reported back through getQueueStatus.
///
/// **Every posting is idempotent, and that is not optional.** A handheld on warehouse wifi loses
/// responses routinely — the request lands, the reply never arrives, the queue retries. Without
/// a replay guard the retry stages a second row for the same physical count. So the client mints
/// one key per captured transaction and HSMobileOpsPostQueue's unique index on IdempotencyKey is
/// what makes a duplicate insert impossible rather than merely unlikely - checking for an
/// existing row and then inserting is a race two concurrent retries would both win.
///
/// **Quantities are taken from the request, never re-derived.** The operator counted something.
/// Posting what the order expected instead would quietly paper over a real short delivery, which
/// is the single most damaging thing a receiving app can do.
/// </summary>
class HSMobileOpsPostingService
{
}

Method.Source:
/// <summary>
/// Registers a purchase order delivery - quantity, batch and put-away location - against
/// its purchase order line. Deliberately does not post a product receipt.
///
/// **No PurchFormLetter, no PurchParmTable, no PurchParmLine.** An earlier version of this
/// method built all three, purely to feed PurchFormLetter's PackingSlip posting - see
/// [registerLine] below, adapted from a published item-registration pattern (posting a
/// product receipt with item registration, via PurchFormLetter/InventTransWMS_Register -
/// shabibax.wordpress.com, June 2023) - and that posting step is gone now, on explicit
/// instruction: the handheld's job is to register what physically arrived, not to post the
/// formal receipt: that happens later, as its own step, outside this app. What
/// InventTransWMS_Register actually changes - the real InventTrans row, Ordered status to
/// Registered, with the batch and location now attached - never depended on the parm-table
/// machinery at all; that machinery existed only because PurchFormLetter needed it, and nothing
/// here calls PurchFormLetter any more.
///
/// Each line is checked against RemainPurchPhysical *read inside this transaction*, not
/// against whatever the client believed when the scan happened. That is what stops a second
/// worker's overlapping capture from over-registering a line two people scanned without
/// knowing about each other - the same guard postTransfer already had for shipping/receiving.
/// </summary>
public HSMobileOpsPostResponse postProductReceipt(HSMobileOpsPostRequest _request)
{
    HSMobileOpsPostResponse      response = new HSMobileOpsPostResponse();
    PurchTable                   purchTable;
    DataAreaId                   company;
    str                          problem;

    response.parmSuccess(false);

    // Reference (the vendor delivery note) is no longer required - the device stopped
    // capturing it once receiving became register-only, since there is no product-receipt
    // journal left for a GRN to reconcile against. See ReceivingStep.PACKING_SLIP.
    problem = HSMobileOpsPostingService::validate(_request, false);
    if (problem)
    {
        response.parmErrorCode(problem);
        response.parmMessage(problem == 'SERIAL_COUNT'
            ? 'The serial numbers scanned do not match the quantity'
            : 'The posting request was incomplete');
        return response;
    }

    company = _request.parmDataAreaId();

    changecompany (company)
    {
        purchTable = null;

        // Landing is idempotent the same way processing used to be - see the class doc.
        // A replay of an already-staged request is not an error, whatever became of it since.
        if (HSMobileOpsPostQueue::findByKey(_request.parmIdempotencyKey()).RecId)
        {
            if (_request.parmResubmit())
            {
                problem = HSMobileOpsPostingService::reopenChecked(HSMobileOpsPostQueue::findByKey(_request.parmIdempotencyKey()).RecId);
                if (problem)
                {
                    response.parmErrorCode('QTY_NOT_AVAILABLE');
                    response.parmMessage(problem);
                    return response;
                }
            }
            response.parmSuccess(true);
            response.parmDocumentNumber('');
            HSMobileOpsPostingService::processNow(_request, response);
            return response;
        }

        select firstOnly RecId, PurchId
            from purchTable
            where purchTable.PurchId == _request.parmSourceId();

        if (!purchTable.RecId)
        {
            response.parmErrorCode('NOT_FOUND');
            response.parmMessage(strFmt('No purchase order %1', _request.parmSourceId()));
            return response;
        }
        problem = HSMobileOpsWarehouseFreeze::frozenMessage(HSMobileOpsPostingService::warehouseOf('Registration', _request.parmSourceId()));
        if (problem)
        {
            response.parmErrorCode('WAREHOUSE_FROZEN');
            response.parmMessage(problem);
            return response;
        }

        try
        {
            HSMobileOpsPostingService::stage(_request, 'Registration');
        }
        catch (Exception::Error)
        {
            response.parmErrorCode('STAGING_FAILED');
            response.parmMessage(HSMobileOpsPostingService::lastError());
            return response;
        }
        catch (Exception::DuplicateKeyException)
        {
            // Only a genuine idempotency-key replay is a success here - the other request
            // that carried this key won the race and its row is really there. Any other
            // duplicate-key failure (a RecId collision from a broken sequence, say) is a
            // real failure and must not be reported as done.
            if (HSMobileOpsPostQueue::findByKey(_request.parmIdempotencyKey()).RecId)
            {
                response.parmSuccess(true);
                response.parmDocumentNumber('');
                return response;
            }

            response.parmErrorCode('STAGING_FAILED');
            response.parmMessage(strFmt(
                'Duplicate-key failure staging %1 and no row exists for this key - the RecId '
              + 'sequence for HSMobileOpsPostQueue is likely not advancing.',
                _request.parmSourceId()));
            return response;
        }

        response.parmSuccess(true);
        response.parmDocumentNumber('');
        HSMobileOpsPostingService::processNow(_request, response);
    }

    return response;
}

/// <summary>
/// Lands one request in HSMobileOpsPostQueue at Pending. The one INSERT postProductReceipt
/// and postTransfer actually wait on - see the class doc on why the rest happens later.
/// </summary>
private static void stage(HSMobileOpsPostRequest _request, str _documentType)
{
    HSMobileOpsPostQueue postQueue;
    str                  problem;

    ttsbegin;

    // In the same transaction as the insert, holding the lines: a second worker's posting of
    // the same line waits here, then sees this row. Refused now, it costs them a message at
    // the door rather than a failed posting found later. Stored Failed, not dropped: a
    // supervisor can then see it and act on it (Mobile posting queue) with nothing rescanned.
    problem = HSMobileOpsPostingService::stagingProblem(
        _documentType, _request.parmSourceId(), _request.parmLinesJson());

    postQueue.clear();
    postQueue.IdempotencyKey  = _request.parmIdempotencyKey();
    postQueue.DocumentType    = _documentType;
    postQueue.SourceId        = _request.parmSourceId();
    postQueue.Reference       = _request.parmReference();
    postQueue.UserName        = _request.parmUserName();
    postQueue.PersonnelNumber = _request.parmPersonnelNumber();
    postQueue.DeviceId        = _request.parmDeviceId();
    postQueue.LinesJson       = _request.parmLinesJson();
    postQueue.LineCount       = HSMobileOpsPostingService::parseLines(_request.parmLinesJson()).elements();
    postQueue.Warehouse       = HSMobileOpsPostingService::warehouseOf(_documentType, _request.parmSourceId());
    postQueue.Status          = problem ? HSMobileOpsPostQueue::statusFailed() : HSMobileOpsPostQueue::statusPending();
    postQueue.ReceivedUtc     = DateTimeUtil::utcNow();
    if (problem)
    {
        postQueue.ErrorMessage = subStr(problem, 1, 250);
        postQueue.ProcessedUtc = postQueue.ReceivedUtc;
    }
    postQueue.insert();

    ttscommit;
}

/// <summary>
/// "Process pending" on the Activity screen: works every Pending row for one company now,
/// rather than waiting for the batch job, and reports what each one became. Also makes sure
/// the recurring batch job exists, so an environment sets itself up the first time someone
/// presses it.
/// </summary>
public HSMobileOpsPostQueueResponse processPending(HSMobileOpsPostQueueRequest _request)
{
    HSMobileOpsPostQueueResponse response = new HSMobileOpsPostQueueResponse();

    if (!_request || !_request.parmDataAreaId())
    {
        response.parmSuccess(false);
        response.parmRows(new List(Types::Class));
        return response;
    }

    try
    {
        HSMobileOpsProcessPendingBatch::ensureScheduled();
    }
    catch
    {
        // Scheduling is a convenience here - pressing the button still processes the rows.
        exceptionTextFallThrough();
    }

    response.parmSuccess(true);
    response.parmRows(HSMobileOpsPostingService::processCompany(_request.parmDataAreaId()));
    return response;
}

/// <summary>
/// "Process pending" on the handheld: works the small Pending rows of one company, oldest
/// first, for as long as a person should wait, and returns what each became. Big postings
/// and whatever is left stay Pending for the batch job. Each row is claimed first
/// (HSMobileOpsPostQueue::claim), so this and the batch job never work the same row.
/// </summary>
public static List processCompany(DataAreaId _company)
{
    HSMobileOpsPostQueue postQueue;
    HSMobileOpsPostQueue processed;
    List                 rows    = new List(Types::Class);
    utcdatetime          started = DateTimeUtil::utcNow();

    changecompany (_company)
    {
        HSMobileOpsPostQueue::failInterrupted();

        while select RecId, DocumentType from postQueue
            order by ReceivedUtc asc
            where postQueue.Status    == HSMobileOpsPostQueue::statusPending()
               && postQueue.LineCount <= HSMobileOpsPostingService::inlineLineLimit()
        {
            if (DateTimeUtil::getDifference(DateTimeUtil::utcNow(), started) >= HSMobileOpsPostingService::inlineSeconds())
            {
                break;
            }

            HSMobileOpsPostingService::processRow(postQueue.RecId, postQueue.DocumentType);

            processed = null;
            select firstOnly processed
                where processed.RecId == postQueue.RecId;

            if (processed.RecId)
            {
                rows.addEnd(HSMobileOpsPostingService::toEntry(processed));
            }
        }
    }

    return rows;
}

/// <summary>
/// One batch task's work (HSMobileOpsPostingWorker): the Pending rows of one warehouse, oldest
/// first, one after the other, until none are left or [workerSeconds] have passed. Postings of
/// one warehouse stay in sequence because they are the ones that would wait on each other's
/// stock rows. A posting already started always runs to its end, however long that takes.
///
/// Stopping on time is what lets the recurring job come round again: it cannot start its next
/// run until every task of this one has ended. An error that gets past the posting's own
/// handling ends this task; the row stays Processing for failInterrupted, not worked twice.
/// </summary>
public static void processWarehouse(DataAreaId _company, InventLocationId _warehouse)
{
    HSMobileOpsPostQueue postQueue;
    utcdatetime          started = DateTimeUtil::utcNow();

    changecompany (_company)
    {
        do
        {
            postQueue = null;
            select firstOnly RecId, DocumentType from postQueue
                order by ReceivedUtc asc
                where postQueue.Status    == HSMobileOpsPostQueue::statusPending()
                   && postQueue.Warehouse == _warehouse
                   && (postQueue.DocumentType == 'Registration'
                    || postQueue.DocumentType == 'TransferShipment'
                    || postQueue.DocumentType == 'TransferReceipt');

            if (!postQueue.RecId)
            {
                break;
            }

            try
            {
                HSMobileOpsPostingService::processRow(postQueue.RecId, postQueue.DocumentType);
            }
            catch
            {
                exceptionTextFallThrough();
                break;
            }
        }
        while (DateTimeUtil::getDifference(DateTimeUtil::utcNow(), started) < HSMobileOpsPostingService::workerSeconds());
    }
}

/// <summary>The recurring job's check for postings that died part way, for one company.</summary>
public static void failInterruptedIn(DataAreaId _company)
{
    changecompany (_company)
    {
        HSMobileOpsPostQueue::failInterrupted();
    }
}

/// <summary>Works one row by its document type. Each method below claims the row first.</summary>
private static void processRow(RecId _recId, str _documentType)
{
    switch (_documentType)
    {
        case 'Registration':
            HSMobileOpsPostingService::processReceiptQueueEntry(_recId);
            break;
        case 'TransferShipment':
            HSMobileOpsPostingService::processTransferQueueEntry(_recId, true);
            break;
        case 'TransferReceipt':
            HSMobileOpsPostingService::processTransferQueueEntry(_recId, false);
            break;
    }
}

/// <summary>
/// The most lines worked while someone waits - Post immediately, Process pending, Retry. A
/// 100 line order took 129 s on the dev VM, past the handheld's two minutes, and holds a web
/// request all that time. Anything bigger goes straight to the batch job.
/// </summary>
public static int inlineLineLimit()
{
    return 50;
}

/// <summary>How long Process pending starts new postings for, inside the handheld's two minutes.</summary>
private static int inlineSeconds()
{
    return 60;
}

/// <summary>How long a batch task starts new postings for - see [processWarehouse].</summary>
private static int workerSeconds()
{
    return 300;
}

/// <summary>
/// Times a posting is worked again after losing to another one: a deadlock, an update conflict
/// or a duplicate key. Everything it did was rolled back, so this cannot book anything twice.
/// Postings run side by side now, so these are ordinary events that should not reach a
/// supervisor unless they keep happening.
/// </summary>
private static int deadlockRetries()
{
    return 3;
}

/// <summary>
/// The warehouse whose stock a posting moves, which decides the batch task that works it: the
/// order's own, its first line's when the header has none, and for a transfer the end being
/// posted. Blank is fine - those rows simply share one task.
/// </summary>
private static InventLocationId warehouseOf(str _documentType, str _sourceId)
{
    PurchTable          purchTable;
    PurchLine           purchLine;
    InventTransferTable transferTable;

    switch (_documentType)
    {
        case 'Registration':
            select firstOnly InventLocationId from purchTable
                where purchTable.PurchId == _sourceId;
            if (purchTable.InventLocationId)
            {
                return purchTable.InventLocationId;
            }
            select firstOnly InventDimId from purchLine
                order by LineNumber
                where purchLine.PurchId == _sourceId;
            return InventDim::find(purchLine.InventDimId).InventLocationId;
        case 'TransferShipment':
            select firstOnly InventLocationIdFrom from transferTable
                where transferTable.TransferId == _sourceId;
            return transferTable.InventLocationIdFrom;
        case 'TransferReceipt':
            select firstOnly InventLocationIdTo from transferTable
                where transferTable.TransferId == _sourceId;
            return transferTable.InventLocationIdTo;
    }
    return '';
}

/// <summary>
/// "Post immediately" on the handheld (Settings > Posting, feedback 301e5d0e): the request
/// just staged - or staged before, for a resend - is worked now instead of waiting for the
/// batch job or "Process pending", and the response says what it became. Called inside the
/// company of the request. Without ProcessNow nothing changes: the row stays Pending. Nor for
/// a big posting (inlineLineLimit): nobody should stand waiting for it, and the batch job has it.
/// </summary>
private static void processNow(HSMobileOpsPostRequest _request, HSMobileOpsPostResponse _response)
{
    HSMobileOpsPostQueue postQueue;

    postQueue = HSMobileOpsPostQueue::findByKey(_request.parmIdempotencyKey());
    if (!postQueue.RecId)
    {
        return;
    }
    // A Failed row is said whatever the setting: without ProcessNow it read as accepted.
    if (!_request.parmProcessNow() && postQueue.Status != HSMobileOpsPostQueue::statusFailed())
    {
        return;
    }
    if (postQueue.Status == HSMobileOpsPostQueue::statusPending()
     && postQueue.LineCount <= HSMobileOpsPostingService::inlineLineLimit())
    {
        HSMobileOpsPostingService::processRow(postQueue.RecId, postQueue.DocumentType);
        postQueue = HSMobileOpsPostQueue::findByKey(_request.parmIdempotencyKey());
    }
    _response.parmQueueStatus(postQueue.Status);
    _response.parmQueueMessage(postQueue.ErrorMessage);
    // Auto GRN: the product receipt number, shown on the handheld's summary.
    if (postQueue.GrnId)
    {
        _response.parmDocumentNumber(postQueue.GrnId);
    }
}

/// <summary>
/// Retry on the Mobile posting queue form: a Failed row reopened and worked now, from the
/// lines staged on it - a big one is left Pending for the batch job. Called inside the row's
/// company. The reason when it could not be reopened - not Failed, or the quantity has gone
/// to someone else since - else blank.
/// </summary>
public static str retryRow(RecId _recId)
{
    HSMobileOpsPostQueue postQueue;
    str                  problem;

    select firstOnly DocumentType, Status, LineCount from postQueue
        where postQueue.RecId == _recId;

    if (postQueue.Status != HSMobileOpsPostQueue::statusFailed())
    {
        return strFmt('It is %1. Only a failed posting can be retried.', postQueue.Status);
    }

    problem = HSMobileOpsPostingService::reopenChecked(_recId);
    if (problem)
    {
        return problem;
    }

    if (postQueue.LineCount <= HSMobileOpsPostingService::inlineLineLimit())
    {
        HSMobileOpsPostingService::processRow(_recId, postQueue.DocumentType);
    }
    return '';
}

/// <summary>
/// A Failed row back to Pending, if what it asks for is still there for it. The reason if not -
/// the row stays Failed, and can be asked for again. Any other status is left alone, blank.
/// </summary>
private static str reopenChecked(RecId _recId)
{
    HSMobileOpsPostQueue postQueue;
    str                  problem;

    ttsbegin;
    select firstOnly postQueue
        where postQueue.RecId == _recId;
    if (postQueue.Status == HSMobileOpsPostQueue::statusFailed())
    {
        problem = HSMobileOpsPostingService::stagingProblem(
            postQueue.DocumentType, postQueue.SourceId, postQueue.LinesJson);
        if (!problem)
        {
            HSMobileOpsPostQueue::reopen(_recId);
        }
    }
    ttscommit;

    return problem;
}

/// <summary>
/// Whether these lines can be staged with what other workers have already staged: the reason
/// if not, else blank. Call inside a transaction: the lines stay locked to its end, so two
/// postings of one line go through this one after the other. Lines are locked in line order,
/// summed first (one line can come in several times, one per batch), so two postings cannot
/// deadlock each other here. A line that is not there is left for processing to report.
/// </summary>
private static str stagingProblem(str _documentType, str _sourceId, str _linesJson)
{
    Map                 requested = new Map(Types::Real, Types::Real);
    Map                 availableByLine = new Map(Types::Real, Types::Real);
    Map                 staged;
    ListEnumerator      lines     = HSMobileOpsPostingService::parseLines(_linesJson).getEnumerator();
    MapEnumerator       lineEnum;
    HSMobileOpsPostLine postLine;
    PurchLine           purchLine;
    InventTransferLine  transferLine;
    LineNum             lineNumber;
    InventQty           quantity;
    InventQty           stagedForLine;
    InventQty           available;

    while (lines.moveNext())
    {
        postLine = lines.current();
        quantity = postLine.parmQuantity()
            + (requested.exists(postLine.parmLineNumber()) ? requested.lookup(postLine.parmLineNumber()) : 0);
        requested.insert(postLine.parmLineNumber(), quantity);
    }

    lineEnum = requested.getEnumerator();
    while (lineEnum.moveNext())
    {
        lineNumber = lineEnum.currentKey();
        quantity   = lineEnum.currentValue();

        if (_documentType == 'Registration')
        {
            purchLine = null;
            select pessimisticLock firstOnly purchLine
                where purchLine.PurchId    == _sourceId
                   && purchLine.LineNumber == lineNumber;
            if (!purchLine.RecId)
            {
                continue;
            }
            available = HSMobileOpsPostingService::orderedQty(purchLine);
        }
        else
        {
            transferLine = null;
            select pessimisticLock firstOnly transferLine
                where transferLine.TransferId == _sourceId
                   && transferLine.LineNum    == lineNumber;
            if (!transferLine.RecId)
            {
                continue;
            }
            available = _documentType == 'TransferShipment'
                ? transferLine.QtyRemainShip
                : transferLine.QtyShipped - transferLine.QtyReceived;
        }

        availableByLine.insert(lineNumber, available);
    }

    // Read once, after every lock: whoever held them has finished, and this sees what they did.
    staged   = HSMobileOpsPostingService::stagedByLine(_documentType, _sourceId);
    lineEnum = requested.getEnumerator();
    while (lineEnum.moveNext())
    {
        lineNumber = lineEnum.currentKey();
        quantity   = lineEnum.currentValue();
        if (!availableByLine.exists(lineNumber))
        {
            continue;
        }
        available     = availableByLine.lookup(lineNumber);
        stagedForLine = staged.exists(lineNumber) ? staged.lookup(lineNumber) : 0;

        if (quantity > available - stagedForLine)
        {
            return strFmt('Line %1: %2 requested but only %3 left',
                    HSMobileOpsPostingService::plainQty(lineNumber),
                    HSMobileOpsPostingService::plainQty(quantity),
                    HSMobileOpsPostingService::plainQty(max(available - stagedForLine, 0)))
                + (stagedForLine > 0
                    ? strFmt(' - %1 more sent from handhelds is waiting to post', HSMobileOpsPostingService::plainQty(stagedForLine))
                    : '');
        }
    }

    return '';
}

/// <summary>A quantity or line number for a worker to read: 10, not 10.00; 2.50 stays.</summary>
public static str plainQty(real _value)
{
    return num2str(_value, 0, _value == trunc(_value) ? 0 : 2, 1, 0);
}

/// <summary>
/// Change quantity on the Mobile posting queue form: new quantities for a Failed posting, one
/// per line in the order of its lines, 0 removing a line. Checked exactly as a new posting is,
/// so it cannot go above what is left on the order: over-delivery stays refused. Lowering one
/// leaves the rest Ordered and open on the order. The device's lines stay in OriginalLinesJson.
/// Called inside the row's company. The reason if not done; if done, it is worked at once.
/// </summary>
public static str changeQuantities(RecId _recId, List _quantities, str _reason)
{
    HSMobileOpsPostQueue postQueue;
    str                  problem;
    str                  linesJson;
    str                  documentType;

    ttsbegin;
    select forUpdate firstOnly postQueue
        where postQueue.RecId == _recId;

    documentType = postQueue.DocumentType;
    problem      = HSMobileOpsPostingService::changeProblem(postQueue, _reason);
    if (!problem)
    {
        problem = HSMobileOpsPostingService::quantityProblem(postQueue.LinesJson, _quantities);
    }
    if (!problem)
    {
        linesJson = HSMobileOpsPostingService::linesWithQuantities(postQueue.LinesJson, _quantities);
        if (strLen(linesJson) > 2000)
        {
            problem = 'That is too many lines to change here.';
        }
    }
    if (!problem)
    {
        problem = HSMobileOpsPostingService::stagingProblem(documentType, postQueue.SourceId, linesJson);
    }
    if (!problem)
    {
        if (!postQueue.OriginalLinesJson)
        {
            postQueue.OriginalLinesJson = postQueue.LinesJson;
        }
        postQueue.LinesJson    = linesJson;
        postQueue.ChangedBy    = curUserId();
        postQueue.ChangedUtc   = DateTimeUtil::utcNow();
        postQueue.ChangeNote   = subStr(_reason, 1, 250);
        postQueue.ErrorMessage = '';
        postQueue.Status       = HSMobileOpsPostQueue::statusPending();
        postQueue.update();
    }
    ttscommit;

    if (problem)
    {
        return problem;
    }

    switch (documentType)
    {
        case 'Registration':
            HSMobileOpsPostingService::processReceiptQueueEntry(_recId);
            break;
        case 'TransferShipment':
            HSMobileOpsPostingService::processTransferQueueEntry(_recId, true);
            break;
        case 'TransferReceipt':
            HSMobileOpsPostingService::processTransferQueueEntry(_recId, false);
            break;
    }
    return '';
}

/// <summary>
/// Cancel posting on the Mobile posting queue form: closes a Failed posting, posting nothing.
/// The handheld holding it clears its card (PostingFollowUp). The reason if not done.
/// </summary>
public static str cancelPosting(RecId _recId, str _reason)
{
    HSMobileOpsPostQueue postQueue;
    str                  problem;

    ttsbegin;
    select forUpdate firstOnly postQueue
        where postQueue.RecId == _recId;

    problem = HSMobileOpsPostingService::changeProblem(postQueue, _reason);
    if (!problem)
    {
        postQueue.ChangedBy    = curUserId();
        postQueue.ChangedUtc   = DateTimeUtil::utcNow();
        postQueue.ChangeNote   = subStr(_reason, 1, 250);
        postQueue.ErrorMessage = subStr(strFmt('Cancelled by %1: %2', curUserId(), _reason), 1, 250);
        postQueue.Status       = HSMobileOpsPostQueue::statusCancelled();
        postQueue.shrinkLines();
        postQueue.update();
    }
    ttscommit;

    return problem;
}

private static str changeProblem(HSMobileOpsPostQueue _postQueue, str _reason)
{
    if (!_postQueue.RecId)
    {
        return 'That posting is no longer there.';
    }
    if (_postQueue.Status != HSMobileOpsPostQueue::statusFailed())
    {
        return strFmt('It is %1. Only a failed posting can be changed or cancelled.', _postQueue.Status);
    }
    if (!strLTrim(strRTrim(_reason)))
    {
        return 'Enter a reason.';
    }
    return '';
}

/// <summary>
/// Whether these quantities can replace the lines' own. A line with serial numbers carries one
/// number per unit, so it can only stay as it is or be removed.
/// </summary>
private static str quantityProblem(str _linesJson, List _quantities)
{
    ListEnumerator      lines      = HSMobileOpsPostingService::parseLines(_linesJson).getEnumerator();
    ListEnumerator      quantities = _quantities.getEnumerator();
    HSMobileOpsPostLine postLine;
    real                quantity;
    boolean             anything;

    while (lines.moveNext() && quantities.moveNext())
    {
        postLine = lines.current();
        quantity = quantities.current();

        if (quantity < 0)
        {
            return 'A quantity cannot be below zero.';
        }
        if (postLine.parmSerialIds().elements() && quantity != 0 && quantity != postLine.parmQuantity())
        {
            return strFmt('Line %1 has serial numbers: it can stay at %2, or be removed with 0.',
                HSMobileOpsPostingService::plainQty(postLine.parmLineNumber()),
                HSMobileOpsPostingService::plainQty(postLine.parmQuantity()));
        }
        if (quantity > 0)
        {
            anything = true;
        }
    }
    return anything ? '' : 'Every quantity is 0. To post nothing, use Cancel posting.';
}

/// <summary>The lines JSON with its quantities replaced: everything else as the device sent it.</summary>
private static str linesWithQuantities(str _linesJson, List _quantities)
{
    System.Object                 parsedObj = Newtonsoft.Json.Linq.JArray::Parse(_linesJson);
    Newtonsoft.Json.Linq.JArray   jArray    = parsedObj;
    Newtonsoft.Json.Linq.JObject  jLine;
    Newtonsoft.Json.Linq.JToken   jQuantity;
    ListEnumerator                quantities = _quantities.getEnumerator();
    container                     values;
    real                          quantity;
    int                           i;

    while (quantities.moveNext())
    {
        values += [quantities.current()];
    }
    // Last first: removing a line moves the ones after it.
    for (i = jArray.get_Count() - 1; i >= 0; i--)
    {
        quantity = conPeek(values, i + 1);
        if (quantity == 0)
        {
            jArray.RemoveAt(i);
        }
        else
        {
            jLine     = jArray.get_Item(i);
            jQuantity = Newtonsoft.Json.Linq.JToken::Parse(num2str(quantity, 0, 6, 1, 0));
            jLine.set_Item('Quantity', jQuantity);
        }
    }
    return Newtonsoft.Json.JsonConvert::SerializeObject(jArray);
}

/// <summary>
/// Quantity per line on rows of this document that are staged or being worked - spoken for,
/// not yet in the order's own figures.
/// </summary>
private static Map stagedByLine(str _documentType, str _sourceId)
{
    HSMobileOpsPostQueue postQueue;
    Map                  staged = new Map(Types::Real, Types::Real);
    ListEnumerator       lines;
    HSMobileOpsPostLine  postLine;
    InventQty            quantity;

    while select LinesJson from postQueue
        index hint SourceIdx
        where postQueue.SourceId     == _sourceId
           && postQueue.DocumentType == _documentType
           && (postQueue.Status      == HSMobileOpsPostQueue::statusPending()
            || postQueue.Status      == HSMobileOpsPostQueue::statusProcessing())
    {
        lines = HSMobileOpsPostingService::parseLines(postQueue.LinesJson).getEnumerator();
        while (lines.moveNext())
        {
            postLine = lines.current();
            quantity = postLine.parmQuantity()
                + (staged.exists(postLine.parmLineNumber()) ? staged.lookup(postLine.parmLineNumber()) : 0);
            staged.insert(postLine.parmLineNumber(), quantity);
        }
    }

    return staged;
}

/// <summary>
/// The most recent 50 requests for one company, whatever their status - Pending, Registered
/// or Failed alike. What the Activity screen's status list is built from. With
/// IdempotencyKeys, those postings instead: a key with no row is simply not in the answer.
/// </summary>
public HSMobileOpsPostQueueResponse getQueueStatus(HSMobileOpsPostQueueRequest _request)
{
    HSMobileOpsPostQueueResponse response = new HSMobileOpsPostQueueResponse();
    HSMobileOpsPostQueue         postQueue;
    List                         rows = new List(Types::Class);
    DataAreaId                   company;
    // 'count' is a reserved word in X++ (the aggregate).
    int                          rowCount;
    ListEnumerator               keys;

    if (!_request || !_request.parmDataAreaId())
    {
        response.parmSuccess(false);
        response.parmRows(rows);
        return response;
    }

    company = _request.parmDataAreaId();

    changecompany (company)
    {
        if (_request.parmIdempotencyKeys())
        {
            keys = strSplit(_request.parmIdempotencyKeys(), ',').getEnumerator();
            while (keys.moveNext())
            {
                postQueue = HSMobileOpsPostQueue::findByKey(keys.current());
                if (postQueue.RecId)
                {
                    rows.addEnd(HSMobileOpsPostingService::toEntry(postQueue));
                }
            }
            response.parmSuccess(true);
            response.parmRows(rows);
            return response;
        }

        while select postQueue
            order by ReceivedUtc desc
        {
            rows.addEnd(HSMobileOpsPostingService::toEntry(postQueue));

            rowCount++;
            if (rowCount >= 50)
            {
                break;
            }
        }
    }

    response.parmSuccess(true);
    response.parmRows(rows);
    return response;
}

private static HSMobileOpsPostQueueEntry toEntry(HSMobileOpsPostQueue _postQueue)
{
    HSMobileOpsPostQueueEntry entry = new HSMobileOpsPostQueueEntry();

    entry.parmSourceId(_postQueue.SourceId);
    entry.parmDocumentType(_postQueue.DocumentType);
    entry.parmStatus(_postQueue.Status);
    entry.parmErrorMessage(_postQueue.ErrorMessage);
    entry.parmReceivedUtc(_postQueue.ReceivedUtc);
    entry.parmProcessedUtc(_postQueue.ProcessedUtc);
    entry.parmUserName(_postQueue.UserName);
    // Not a 200 KB order in a list of 50: the count says enough.
    entry.parmLinesJson(strLen(_postQueue.LinesJson) > 2000 ? '' : _postQueue.LinesJson);
    entry.parmLineCount(_postQueue.LineCount);
    entry.parmIdempotencyKey(_postQueue.IdempotencyKey);
    entry.parmGrnId(_postQueue.GrnId);

    return entry;
}

/// <summary>
/// The registration work postProductReceipt used to do inline, unchanged except for where
/// its outcome goes: onto the queue row itself, in its own transaction, separate from the
/// registration attempt so a failed attempt still leaves a row a supervisor can see.
/// </summary>
private static void processReceiptQueueEntry(RecId _queueRecId)
{
    HSMobileOpsPostQueue postQueue;
    PurchTable           purchTable;
    PurchLine            purchLine;
    HSMobileOpsPostLine  postLine;
    List                 lines;
    ListEnumerator       enumerator;
    InventQty            requested;
    InventQty            available;
    str                  failMessage;
    PackingSlipId        grnId;
    str                  grnStage;
    int                  infologFrom = infologLine();

    select firstOnly postQueue
        where postQueue.RecId == _queueRecId;

    // Staged before its warehouse was frozen: it waits, Pending, until the count is done.
    if (postQueue.RecId && HSMobileOpsWarehouseFreeze::findActive(
            HSMobileOpsPostingService::warehouseOf(postQueue.DocumentType, postQueue.SourceId)).RecId)
    {
        return;
    }
    // Claimed, not just checked: the batch job and the button may both have selected it.
    if (!postQueue.RecId || !HSMobileOpsPostQueue::claim(postQueue.RecId))
    {
        return;
    }

    failMessage = '';

    try
    {
        grnStage = '';
        HSMobileOpsPostingService::ensureBatches(postQueue.LinesJson);

        ttsbegin;

        purchTable = null;
        select firstOnly RecId, PurchId
            from purchTable
            where purchTable.PurchId == postQueue.SourceId;

        if (!purchTable.RecId)
        {
            failMessage = strFmt('No purchase order %1', postQueue.SourceId);
        }
        else
        {
            lines      = HSMobileOpsPostingService::parseLines(postQueue.LinesJson);
            enumerator = lines.getEnumerator();
            // Never Registered with nothing registered.
            if (!lines.elements())
            {
                failMessage = 'This posting has no lines that can be read';
            }

            while (enumerator.moveNext() && !failMessage)
            {
                postLine  = enumerator.current();
                purchLine = null;

                // Locked (pessimisticLock - it implies forUpdate), not optimistic: two devices'
                // registrations of the same line ran 2 s apart (BSP-PO-000161712, 10 Oct),
                // both read 2 still Ordered, and the second registered nothing yet was
                // reported Registered. Locked, the second waits for the first to commit and
                // then reads what is really left.
                select pessimisticLock firstOnly purchLine
                    where purchLine.PurchId    == purchTable.PurchId
                       && purchLine.LineNumber == postLine.parmLineNumber();

                if (!purchLine.RecId)
                {
                    failMessage = strFmt(
                        'Line %1 is not on %2',
                        postLine.parmLineNumber(), purchTable.PurchId);
                }
                else
                {
                    requested = postLine.parmQuantity();
                    // What is still Ordered in InventTrans - registration converts Ordered to
                    // Registered, while RemainPurchPhysical only falls at product receipt. With
                    // RemainPurchPhysical two devices each registered all of a 2-piece line
                    // (BSP-PO-000161711, 10 Oct: 4 registered).
                    available = HSMobileOpsPostingService::orderedQty(purchLine);

                    // Checked again here, not only on the device or at staging time - the
                    // request may have sat Pending a while, and someone else may have
                    // received part of the same line in the meantime.
                    if (requested > available)
                    {
                        failMessage = strFmt(
                            'Line %1: %2 requested but only %3 left',
                            HSMobileOpsPostingService::plainQty(postLine.parmLineNumber()),
                            HSMobileOpsPostingService::plainQty(requested),
                            HSMobileOpsPostingService::plainQty(available));
                    }
                    else
                    {
                        // Registers this line's quantity, batch and location directly
                        // against its own InventTrans - every line, not only ones carrying
                        // a batch or a location, because registering the quantity is the
                        // point even when neither dimension needs to change.
                        HSMobileOpsPostingService::registerLine(
                            purchLine,
                            postLine,
                            HSMobileOpsPostingService::inventQtyOf(purchLine, requested, available));

                        // Whatever claim was on this line is done its job the moment it
                        // registers - a no-op outside LineClaim mode.
                        HSMobileOpsLineClaim::release(
                            HSMobileOpsProcessSetup::processReceiving(),
                            purchTable.PurchId,
                            purchLine.LineNumber,
                            postQueue.UserName);
                    }
                }
            }
        }

        // Auto GRN (Mobile process setup, Receiving): the registered quantity is posted as a
        // product receipt in this same transaction - registered and received together, or
        // neither, so a failed GRN leaves nothing half done to find.
        if (!failMessage
         && HSMobileOpsProcessSetup::find(HSMobileOpsProcessSetup::processReceiving()).AutoGrn)
        {
            grnStage = 'GRN not posted - ';
            grnId    = HSMobileOpsPostingService::postGrn(purchTable.PurchId);
            grnStage = '';
        }

        if (failMessage)
        {
            ttsabort;
        }
        else
        {
            ttscommit;
        }
    }
    catch (Exception::Error)
    {
        failMessage = grnStage + HSMobileOpsPostingService::lastError(infologFrom);
        grnId       = '';
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() < HSMobileOpsPostingService::deadlockRetries())
        {
            retry;
        }
        failMessage = 'The registration deadlocked and was rolled back. Retry.';
        grnId       = '';
    }
    catch (Exception::UpdateConflict)
    {
        if (xSession::currentRetryCount() < HSMobileOpsPostingService::deadlockRetries())
        {
            retry;
        }
        failMessage = 'Someone else kept changing the same records. Nothing was posted. Retry.';
        grnId       = '';
    }
    catch (Exception::DuplicateKeyException)
    {
        // Two warehouses receiving one new batch number at once: both create its master
        // record, the second loses. Worked again, it finds the first one's record there.
        if (xSession::currentRetryCount() < HSMobileOpsPostingService::deadlockRetries())
        {
            retry;
        }
        failMessage = 'A record this posting creates kept appearing at the same moment. Nothing was posted. Retry.';
        grnId       = '';
    }

    // Separate from the transaction above on purpose - the queue row's own outcome has to
    // persist whether that transaction committed or aborted.
    ttsbegin;
    select forUpdate postQueue
        where postQueue.RecId == _queueRecId;
    if (failMessage)
    {
        postQueue.Status       = HSMobileOpsPostQueue::statusFailed();
        postQueue.ErrorMessage = subStr(failMessage, 1, 250);
    }
    else
    {
        postQueue.Status = HSMobileOpsPostQueue::statusRegistered();
        postQueue.shrinkLines();
        postQueue.GrnId  = grnId;
    }
    postQueue.ProcessedUtc = DateTimeUtil::utcNow();
    postQueue.update();
    ttscommit;
}

/// <summary>
/// Auto GRN: posts the product receipt for the order's registered quantity (PurchUpdate::
/// Recorded), numbered from the GRN number sequence on Mobile process setup. Called inside
/// processReceiptQueueEntry's transaction, right after the lines registered. Throws when
/// nothing was posted, so the registration rolls back with it.
/// </summary>
private static PackingSlipId postGrn(PurchId _purchId)
{
    HSMobileOpsProcessSetup setup = HSMobileOpsProcessSetup::find(HSMobileOpsProcessSetup::processReceiving());
    PackingSlipId           grnId;
    PurchFormLetter         letter;
    VendPackingSlipJour     slip;

    // Changing a confirmed order (raising a line's quantity, say) takes it back to Approved,
    // and posting then ends with no journal and no message. Said here, before a number is used.
    if (PurchTable::find(_purchId).DocumentState != VersioningDocumentState::Confirmed)
    {
        throw error(strFmt('%1 has been changed and is not confirmed. Confirm it, then retry.', _purchId));
    }

    grnId  = setup.nextGrnId();
    letter = PurchFormLetter::construct(DocumentStatus::PackingSlip);
    letter.update(PurchTable::find(_purchId), grnId,
        DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
        PurchUpdate::Recorded, AccountOrder::None, NoYes::No, NoYes::No);

    // Posting can end with only an infolog message and no journal - nothing to receive, say.
    select firstOnly RecId from slip
        where slip.PurchId       == _purchId
           && slip.PackingSlipId == grnId;
    if (!slip.RecId)
    {
        throw error(strFmt('Product receipt %1 was not posted for %2', grnId, _purchId));
    }

    return grnId;
}

/// <summary>
/// Registers one line: the operator's counted quantity, and the batch and/or put-away
/// location captured for it, applied directly to the line's own InventTrans row.
///
/// Adapted from a published item-registration pattern (posting a product receipt with item
/// registration via PurchFormLetter/InventTransWMS_Register - shabibax.wordpress.com, June
/// 2023), with the PurchFormLetter half removed - see the class doc on [postProductReceipt].
/// Find the line's own Ordered-status InventTrans by InventTransId, build a new InventDim
/// from that transaction's *own* current dimension - not from the purchase line or from
/// scratch - with the batch and/or location laid on top, resolve it through
/// InventDim::findOrCreate, and hand it to InventTransWMS_Register so the conversion happens
/// against the real transaction. This is what actually turns batch-less Ordered quantity
/// into a specific batch and location; setting InventDimId directly on a parm line - the
/// first version of this - does not, because that only told the posting engine which
/// dimension the *received* side should carry, and there is no posting engine step here any
/// more for it to tell.
///
/// Silently a no-op if the line's InventTransId cannot be found - the caller already checked
/// this line is real and outstanding, so that should not happen, but a missing transaction
/// here is not a reason to fail an otherwise-valid registration over the one line it could
/// not resolve. _quantity is in the inventory unit - see [inventQtyOf].
/// </summary>
private static void registerLine(PurchLine _purchLine, HSMobileOpsPostLine _postLine, InventQty _quantity)
{
    InventTrans              inventTrans;
    InventDim                inventDim;
    InventDim                serialDim;
    TmpInventTransWMS        tmpInventTransWMS;
    InventTransWMS_Register  register;
    List                     serials = _postLine.parmSerialIds();
    ListEnumerator           serialEnumerator;
    InventSerialId           serialId;
    boolean                  perUnit;

    inventTrans = InventTrans::findTransId(_purchLine.InventTransId, true);
    if (!inventTrans.RecId)
    {
        return;
    }

    inventDim = inventTrans.inventDim();

    if (_postLine.parmBatchId())
    {
        HSMobileOpsPostingService::ensureBatch(
            inventTrans.ItemId,
            _postLine.parmBatchId(),
            _postLine.parmBatchManufacturingDate(),
            _postLine.parmBatchExpiryDate());
        inventDim.InventBatchId = _postLine.parmBatchId();
    }
    if (_postLine.parmLocationId())
    {
        inventDim.wMSLocationId = _postLine.parmLocationId();
    }
    // Where the item's storage dimension group has inventory status active, D365FO refuses a
    // location without one ("Inventory status cannot be left blank if dimension Location is
    // set"). An order line from an import or integration may carry none; see defaultStatus.
    if (!inventDim.InventStatusId && inventDim.wMSLocationId
     && InventDimGroupSetup::newItemId(inventTrans.ItemId).isDimensionActive(fieldNum(InventDim, InventStatusId)))
    {
        inventDim.InventStatusId = HSMobileOpsPostingService::defaultStatus(inventDim.InventLocationId);
    }

    inventDim = InventDim::findOrCreate(inventDim);

    register = InventTransWMS_Register::newStandard(tmpInventTransWMS);

    inventTrans.InventDimId = inventDim.InventDimId;

    if (serials && serials.elements())
    {
        // The serials the operator scanned. With serial number control each one is a unit
        // of its own (validate has checked one per unit); without it, one serial covers the
        // whole line. Each new serial number gets its master record first, as batches do.
        perUnit = HSMobileOpsDimensionRules::serialPerUnit(InventDimGroupSetup::newItemId(inventTrans.ItemId));
        serialEnumerator = serials.getEnumerator();
        while (serialEnumerator.moveNext())
        {
            serialId = serialEnumerator.current();
            HSMobileOpsPostingService::ensureSerial(inventTrans.ItemId, serialId);
            serialDim.data(inventDim);
            serialDim.InventSerialId = serialId;
            serialDim = InventDim::findOrCreate(serialDim);

            tmpInventTransWMS.clear();
            tmpInventTransWMS.initFromInventTrans(inventTrans);
            tmpInventTransWMS.ItemId      = inventTrans.ItemId;
            tmpInventTransWMS.InventQty   = perUnit ? 1 : _quantity;
            tmpInventTransWMS.InventDimId = serialDim.InventDimId;
            tmpInventTransWMS.insert();
            register.writeTmpInventTransWMS(tmpInventTransWMS, inventTrans, serialDim);
        }
    }
    else
    {
        tmpInventTransWMS.clear();
        tmpInventTransWMS.initFromInventTrans(inventTrans);
        tmpInventTransWMS.ItemId    = inventTrans.ItemId;
        tmpInventTransWMS.InventQty = _quantity;
        tmpInventTransWMS.insert();
        register.writeTmpInventTransWMS(tmpInventTransWMS, inventTrans, inventDim);
    }
    register.updateInvent(inventTrans);
}

/// <summary>
/// The inventory status a receipt takes when its line has none: the warehouse's default,
/// then the warehouse management parameters' default, then - only when there is exactly one
/// non-blocking status in the company, so the choice is not a guess - that one. Blank
/// otherwise, and D365FO's own message then says what is missing.
/// </summary>
private static WHSInventStatusId defaultStatus(InventLocationId _warehouse)
{
    WHSInventStatusId statusId = InventLocation::find(_warehouse).DefaultStatusId;
    WHSInventStatus   status;

    if (!statusId)
    {
        statusId = WHSParameters::find().DefaultStatusId;
    }
    if (!statusId)
    {
        select count(RecId) from status where status.InventStatusBlocking == NoYes::No;
        if (status.RecId == 1)
        {
            select firstonly InventStatusId from status where status.InventStatusBlocking == NoYes::No;
            statusId = status.InventStatusId;
        }
    }
    return statusId;
}

/// <summary>
/// Creates the serial number's master record when the item has never had it - the same
/// reason as ensureBatch: a dimension cannot reference a serial with no InventSerial row.
/// </summary>
private static void ensureSerial(ItemId _itemId, InventSerialId _serialId)
{
    InventSerial inventSerial;

    select firstOnly RecId from inventSerial
        where inventSerial.ItemId         == _itemId
           && inventSerial.InventSerialId == _serialId;

    if (!inventSerial.RecId)
    {
        inventSerial.clear();
        inventSerial.ItemId         = _itemId;
        inventSerial.InventSerialId = _serialId;
        inventSerial.ProdDate       = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        inventSerial.insert();
    }
}

/// <summary>
/// The batches a posting brings, created before its transaction, each in a short one of its
/// own. Created inside, a new batch's row stays locked until the whole order commits, and any
/// other warehouse receiving that batch waits for it: seven workers waited on one 1,000 line
/// order on the dev VM. Left behind if the posting then fails, which is harmless: a batch with
/// no stock, found again by the retry.
/// </summary>
private static void ensureBatches(str _linesJson)
{
    ListEnumerator      enumerator = HSMobileOpsPostingService::parseLines(_linesJson).getEnumerator();
    HSMobileOpsPostLine postLine;
    Set                 done = new Set(Types::String);
    str                 key;

    while (enumerator.moveNext())
    {
        postLine = enumerator.current();
        key      = postLine.parmItemId() + '|' + postLine.parmBatchId();
        if (!postLine.parmItemId() || !postLine.parmBatchId() || done.in(key))
        {
            continue;
        }
        done.add(key);

        try
        {
            ttsbegin;
            HSMobileOpsPostingService::ensureBatch(
                postLine.parmItemId(),
                postLine.parmBatchId(),
                postLine.parmBatchManufacturingDate(),
                postLine.parmBatchExpiryDate());
            ttscommit;
        }
        catch (Exception::DuplicateKeyException)
        {
            // Another posting created it this instant, which is all that was wanted.
            exceptionTextFallThrough();
        }
    }
}

/// <summary>
/// Creates the batch's own master record, if this item and batch combination has never been
/// seen before.
///
/// InventDim::findOrCreate refused a brand new batch number with a plain "Update has been
/// canceled" - confirmed live, with the full dimension in the message, so the dimension
/// values themselves were not the problem. InventBatch is the batch's *master* record - one
/// row per item and batch, holding its manufacturing and expiry dates among other things -
/// and a dimension combination cannot reference a batch that has no master row of its own,
/// the same way an InventDim cannot reference a warehouse location that does not exist in
/// WMSLocation.
///
/// The dates are set only when this call is the one creating the row. An existing batch
/// already has its own dates, decided whenever it was first created - the client does not
/// ask the operator again once HSMobileOpsInquirySvc/validateBatch says a batch is already
/// registered, and this must not silently overwrite an established batch's dates just
/// because a blank date happened to come through on a later line.
///
/// _manufacturingDate is always blank from the Android app now - the operator is only asked
/// for the expiry date on a new batch, not both. Left as its own parameter rather than
/// removed: the field, the contract member and this method's ability to set it all still
/// exist and cost nothing idle, in case a manufacturing date is ever wanted back without
/// touching this method again.
/// </summary>
private static void ensureBatch(
    ItemId _itemId, InventBatchId _batchId, str _manufacturingDate, str _expiryDate)
{
    InventBatch inventBatch;

    select firstOnly RecId from inventBatch
        where inventBatch.ItemId         == _itemId
           && inventBatch.InventBatchId  == _batchId;

    if (!inventBatch.RecId)
    {
        inventBatch.clear();
        inventBatch.ItemId        = _itemId;
        inventBatch.InventBatchId = _batchId;

        if (_manufacturingDate)
        {
            inventBatch.prodDate =
                HSMobileOpsPostingService::parseIsoDate(_manufacturingDate);
        }
        if (_expiryDate)
        {
            inventBatch.ExpDate = HSMobileOpsPostingService::parseIsoDate(_expiryDate);
        }

        inventBatch.insert();
    }
}

/// <summary>
/// 'yyyy-MM-dd' to a Date, or dateNull() for anything that is not exactly that shape.
///
/// Parsed by hand with subStr/str2int rather than str2Date, whose format is a numeric
/// day/month/year *sequence* code this codebase has no existing, verified use of - guessing
/// that code wrong silently reads a correct-looking string as the wrong date, which for an
/// expiry date is a stock-safety mistake, not a cosmetic one. Fixed field positions cannot
/// be misread the same way.
/// </summary>
private static Date parseIsoDate(str _isoDate)
{
    int year;
    int month;
    int day;

    if (!_isoDate || strLen(_isoDate) != 10)
    {
        return dateNull();
    }

    year  = str2int(subStr(_isoDate, 1, 4));
    month = str2int(subStr(_isoDate, 6, 2));
    day   = str2int(subStr(_isoDate, 9, 2));

    if (year <= 0 || month <= 0 || month > 12 || day <= 0 || day > 31)
    {
        return dateNull();
    }

    return mkDate(day, month, year);
}

/// <summary>
/// Posts a transfer order shipment.
///
/// The quantities to ship are written to InventTransferLine.QtyShipNow and the standard
/// InventTransferUpdShip engine is run over the order. Setting QtyShipNow rather than posting
/// the whole order is what makes a partial shipment possible - which is the normal case when
/// a pallet is picked over two shifts.
/// </summary>
public HSMobileOpsPostResponse postTransferShipment(HSMobileOpsPostRequest _request)
{
    return HSMobileOpsPostingService::postTransfer(_request, true);
}

/// <summary>
/// Posts a transfer order receipt.
///
/// Bounded by what is in transit, not by what was ordered - the same rule the read side
/// enforces, checked again here because the client is not the last line of defence.
/// </summary>
public HSMobileOpsPostResponse postTransferReceipt(HSMobileOpsPostRequest _request)
{
    return HSMobileOpsPostingService::postTransfer(_request, false);
}

/// <summary>
/// Shared transfer landing: validates, checks idempotency, stages. See the class doc - the
/// engine run that used to happen here now happens in processTransferQueueEntry instead,
/// triggered later from processPending.
/// </summary>
private static HSMobileOpsPostResponse postTransfer(
    HSMobileOpsPostRequest _request, boolean _shipping)
{
    HSMobileOpsPostResponse response = new HSMobileOpsPostResponse();
    InventTransferTable     transferTable;
    DataAreaId              company;
    str                     problem;

    response.parmSuccess(false);

    problem = HSMobileOpsPostingService::validate(_request, false);
    if (problem)
    {
        response.parmErrorCode(problem);
        response.parmMessage(problem == 'SERIAL_COUNT'
            ? 'The serial numbers scanned do not match the quantity'
            : 'The posting request was incomplete');
        return response;
    }

    company = _request.parmDataAreaId();

    changecompany (company)
    {
        transferTable = null;

        if (HSMobileOpsPostQueue::findByKey(_request.parmIdempotencyKey()).RecId)
        {
            if (_request.parmResubmit())
            {
                problem = HSMobileOpsPostingService::reopenChecked(HSMobileOpsPostQueue::findByKey(_request.parmIdempotencyKey()).RecId);
                if (problem)
                {
                    response.parmErrorCode('QTY_NOT_AVAILABLE');
                    response.parmMessage(problem);
                    return response;
                }
            }
            response.parmSuccess(true);
            response.parmDocumentNumber('');
            HSMobileOpsPostingService::processNow(_request, response);
            return response;
        }

        select firstOnly RecId, TransferId
            from transferTable
            where transferTable.TransferId == _request.parmSourceId();

        if (!transferTable.RecId)
        {
            response.parmErrorCode('NOT_FOUND');
            response.parmMessage(strFmt('No transfer order %1', _request.parmSourceId()));
            return response;
        }
        problem = HSMobileOpsWarehouseFreeze::frozenMessage(HSMobileOpsPostingService::warehouseOf(
            _shipping ? 'TransferShipment' : 'TransferReceipt', _request.parmSourceId()));
        if (problem)
        {
            response.parmErrorCode('WAREHOUSE_FROZEN');
            response.parmMessage(problem);
            return response;
        }

        try
        {
            HSMobileOpsPostingService::stage(
                _request, _shipping ? 'TransferShipment' : 'TransferReceipt');
        }
        catch (Exception::Error)
        {
            response.parmErrorCode('STAGING_FAILED');
            response.parmMessage(HSMobileOpsPostingService::lastError());
            return response;
        }
        catch (Exception::DuplicateKeyException)
        {
            // See the identical guard in postProductReceipt - a real replay only.
            if (HSMobileOpsPostQueue::findByKey(_request.parmIdempotencyKey()).RecId)
            {
                response.parmSuccess(true);
                response.parmDocumentNumber('');
                return response;
            }

            response.parmErrorCode('STAGING_FAILED');
            response.parmMessage(strFmt(
                'Duplicate-key failure staging %1 and no row exists for this key - the RecId '
              + 'sequence for HSMobileOpsPostQueue is likely not advancing.',
                _request.parmSourceId()));
            return response;
        }

        response.parmSuccess(true);
        response.parmDocumentNumber('');
        HSMobileOpsPostingService::processNow(_request, response);
    }

    return response;
}

/// <summary>
/// The transfer-engine work postTransfer used to do inline, unchanged except for where its
/// outcome goes - see the identical note on processReceiptQueueEntry.
/// </summary>
private static void processTransferQueueEntry(RecId _queueRecId, boolean _shipping)
{
    HSMobileOpsPostQueue     postQueue;
    InventTransferTable      transferTable;
    InventTransferLine       transferLine;
    InventTransferParmTable  parmTable;
    InventTransferUpdShip    updShip;
    InventTransferUpdReceive updReceive;
    TransDate                postingDate;
    boolean                  posted;
    HSMobileOpsPostLine      postLine;
    List                     lines;
    ListEnumerator           enumerator;
    InventQty                requested;
    InventQty                shortfall;
    InventQty                available;
    str                      failMessage;
    InventDim                lineDim;
    // Several scans of one line (two batches, two bins) add up: what each line has taken so
    // far in this posting, and - shipping - the batch each line carries and the line each
    // further batch was moved onto.
    Map                      takenByLine   = new Map(Types::Real, Types::Real);
    Map                      batchOfLine   = new Map(Types::Real, Types::String);
    Map                      lineOfBatch   = new Map(Types::String, Types::Real);
    InventQty                taken;
    str                      lineDimKey;
    str                      dimKey;
    str                      batchKey;
    InventSerialId           lineSerial;
    str                      batchProblem;

    select firstOnly postQueue
        where postQueue.RecId == _queueRecId;

    // Staged before its warehouse was frozen: it waits, Pending, until the count is done.
    if (postQueue.RecId && HSMobileOpsWarehouseFreeze::findActive(
            HSMobileOpsPostingService::warehouseOf(postQueue.DocumentType, postQueue.SourceId)).RecId)
    {
        return;
    }
    // Claimed, not just checked: the batch job and the button may both have selected it.
    if (!postQueue.RecId || !HSMobileOpsPostQueue::claim(postQueue.RecId))
    {
        return;
    }

    failMessage = '';
    posted      = false;
    postingDate = DateTimeUtil::date(DateTimeUtil::utcNow());

    try
    {
        // Empty again if a deadlock brought this back round: all of it was rolled back.
        takenByLine = new Map(Types::Real, Types::Real);
        batchOfLine = new Map(Types::Real, Types::String);
        lineOfBatch = new Map(Types::String, Types::Real);
        posted      = false;

        ttsbegin;

        transferTable = null;
        select firstOnly RecId, TransferId
            from transferTable
            where transferTable.TransferId == postQueue.SourceId;

        if (!transferTable.RecId)
        {
            failMessage = strFmt('No transfer order %1', postQueue.SourceId);
        }
        else
        {
            // Zero every now-quantity first - see the identical note this carries over from
            // the inline version.
            if (_shipping)
            {
                update_recordset transferLine
                    setting QtyShipNow = 0
                    where transferLine.TransferId == transferTable.TransferId;
            }
            else
            {
                update_recordset transferLine
                    setting QtyReceiveNow = 0
                    where transferLine.TransferId == transferTable.TransferId;
            }

            // Shipping: the batch and serials the worker scanned are picked on the line before
            // posting (pickLine) - a batch or serial that is a primary dimension otherwise
            // refuses the shipment ("must consequently be specified"). Receiving takes the
            // shipped batch and serial over from transit, as D365FO does.
            lines      = HSMobileOpsPostingService::parseLines(postQueue.LinesJson);
            enumerator = lines.getEnumerator();
            // Never Registered with nothing registered.
            if (!lines.elements())
            {
                failMessage = 'This posting has no lines that can be read';
            }

            while (enumerator.moveNext() && !failMessage)
            {
                postLine     = enumerator.current();
                transferLine = null;

                select forUpdate firstOnly transferLine
                    where transferLine.TransferId == transferTable.TransferId
                       && transferLine.LineNum    == postLine.parmLineNumber();

                if (!transferLine.RecId)
                {
                    failMessage = strFmt(
                        'Line %1 is not on %2',
                        postLine.parmLineNumber(), transferTable.TransferId);
                }
                else
                {
                    requested = postLine.parmQuantity();
                    taken     = takenByLine.exists(transferLine.LineNum) ? takenByLine.lookup(transferLine.LineNum) : 0;
                    // What the line had outstanding before this posting: quantity already
                    // moved onto a new line for another batch still counts against it.
                    available = _shipping
                        ? transferLine.QtyRemainShip + HSMobileOpsPostingService::movedOff(lineOfBatch, transferLine.LineNum, transferTable.TransferId)
                        : transferLine.QtyShipped - transferLine.QtyReceived;

                    // Receiving: the scanned batch must be one shipped on the line.
                    batchProblem = !_shipping && postLine.parmBatchId()
                        ? HSMobileOpsPostingService::unshippedBatch(transferLine, postLine.parmBatchId(), requested)
                        : '';

                    if (taken + requested > available)
                    {
                        failMessage = strFmt(
                            'Line %1: %2 requested but only %3 left',
                            HSMobileOpsPostingService::plainQty(postLine.parmLineNumber()),
                            HSMobileOpsPostingService::plainQty(taken + requested),
                            HSMobileOpsPostingService::plainQty(available));
                    }
                    else if (batchProblem)
                    {
                        failMessage = batchProblem;
                    }
                    else
                    {
                        takenByLine.insert(transferLine.LineNum, taken + requested);

                        // Less than the outstanding quantity is a normal partial shipment
                        // or receipt: "Ship now" / "Receive now" below post exactly the
                        // quantity set here and leave the rest open on the line. Added, not
                        // set: the same line can come several times in one posting.
                        if (_shipping)
                        {
                            // The line's own dimensions are left as they are: batch, serial
                            // and bin go only on the inventory transactions, through the pick
                            // (user, 8 Oct 2026) - the shipment ships what is picked. Several
                            // batches of one line are several picks of that line, not new lines.
                            transferLine.QtyShipNow += requested;
                        }
                        else
                        {
                            transferLine.QtyReceiveNow += requested;
                        }

                        transferLine.update();

                        // Picked already when it was scanned (pickTransferLine): not again -
                        // unless the line is not in fact picked that far (a pick that found
                        // no stock does nothing), then as before.
                        if (_shipping)
                        {
                            // Only what is not picked yet is picked now - whether the app picked
                            // it when scanned or an earlier session did (one lost on the device
                            // with its picks still in D365FO, BSP-TO-000000026).
                            shortfall = (takenByLine.exists(transferLine.LineNum) ? takenByLine.lookup(transferLine.LineNum) : requested)
                                      - HSMobileOpsPostingService::pickedQty(transferLine);
                            if (shortfall > 0)
                            {
                                HSMobileOpsPostingService::pickLine(transferLine, postLine, min(shortfall, requested));
                            }
                            // Picked already: the shipment ships the pick as it is. (Falling
                            // through to the receipt registration here registered the receive
                            // side before anything was shipped - "Total received quantity
                            // exceeds shipped quantity", BSP-TO-000000026.)
                        }
                        else
                        {
                            HSMobileOpsPostingService::registerTransferReceipt(transferLine, postLine, requested);
                        }
                    }
                }
            }

            if (!failMessage)
            {
                parmTable.clear();
                parmTable.initParmDefault();
                parmTable.ParmId     = RunBaseMultiParm::getSysParmId();
                parmTable.TransferId = transferTable.TransferId;
                parmTable.EditLines  = NoYes::Yes;
                parmTable.UpdateType = _shipping
                                     ? InventTransferUpdateType::Shipment
                                     : InventTransferUpdateType::Receive;
                parmTable.TransDate  = postingDate;

                // "Ship now" / "Receive now": only the quantities set on the lines above.
                // "All" ships or receives everything outstanding on the order - one
                // scanned line of a 520-line transfer shipped all 520 lines.
                if (_shipping)
                {
                    parmTable.ShipUpdateQty = InventTransferShipUpdateQty::ShipNow;
                }
                else
                {
                    parmTable.ReceiveUpdateQty = InventTransferReceiveUpdateQty::ReceiveNow;
                }

                parmTable.insert();

                if (_shipping)
                {
                    updShip = InventTransferUpdShip::newParmBuffer(parmTable);
                    updShip.run();
                    posted = updShip.parmIsSomeThingPosted();
                }
                else
                {
                    updReceive = InventTransferUpdReceive::newParmBuffer(parmTable);
                    updReceive.run();
                    posted = updReceive.parmIsSomeThingPosted();
                }

                if (!posted)
                {
                    // The engine reports failure by posting nothing rather than by throwing.
                    failMessage =
                        'The transfer engine posted nothing. Check the order status.';
                }
            }
        }

        if (failMessage)
        {
            ttsabort;
        }
        else
        {
            ttscommit;
        }
    }
    catch (Exception::Error)
    {
        failMessage = HSMobileOpsPostingService::lastError();
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() < HSMobileOpsPostingService::deadlockRetries())
        {
            retry;
        }
        failMessage = 'The posting deadlocked and was rolled back. Retry.';
    }
    catch (Exception::UpdateConflict)
    {
        if (xSession::currentRetryCount() < HSMobileOpsPostingService::deadlockRetries())
        {
            retry;
        }
        failMessage = 'Someone else kept changing the same records. Nothing was posted. Retry.';
    }
    catch (Exception::DuplicateKeyException)
    {
        // Two warehouses receiving one new batch number at once: both create its master
        // record, the second loses. Worked again, it finds the first one's record there.
        if (xSession::currentRetryCount() < HSMobileOpsPostingService::deadlockRetries())
        {
            retry;
        }
        failMessage = 'A record this posting creates kept appearing at the same moment. Nothing was posted. Retry.';
    }

    ttsbegin;
    select forUpdate postQueue
        where postQueue.RecId == _queueRecId;
    if (failMessage)
    {
        postQueue.Status       = HSMobileOpsPostQueue::statusFailed();
        postQueue.ErrorMessage = subStr(failMessage, 1, 250);
    }
    else
    {
        postQueue.Status = HSMobileOpsPostQueue::statusRegistered();
        postQueue.shrinkLines();
    }
    postQueue.ProcessedUtc = DateTimeUtil::utcNow();
    postQueue.update();
    ttscommit;
}

/// <summary>
/// Moves _quantity of a transfer line onto the line for another batch (or single serial) in
/// this posting - a new line of the same order, created the first time that batch comes up
/// (same item, warehouses and dimensions, with that batch) - and returns that line, selected
/// for update. The
/// original line's ordered and outstanding quantities go down by the same amount.
/// </summary>
private static InventTransferLine splitForBatch(
    InventTransferLine _line,
    Map                _lineOfBatch,
    str                _batchKey,
    InventBatchId      _batchId,
    InventSerialId     _serialId,
    InventQty          _quantity)
{
    InventTransferLine original;
    InventTransferLine splitLine;
    InventTransferLine last;
    InventDim          splitDim;
    RecId              splitRecId;

    select forUpdate firstOnly original
        where original.RecId == _line.RecId;
    original.QtyTransfer      -= _quantity;
    original.QtyRemainShip    -= _quantity;
    original.QtyRemainReceive -= _quantity;
    original.update();

    if (_lineOfBatch.exists(_batchKey))
    {
        select forUpdate firstOnly splitLine
            where splitLine.TransferId == original.TransferId
               && splitLine.LineNum    == _lineOfBatch.lookup(_batchKey);
        splitLine.QtyTransfer      += _quantity;
        splitLine.QtyRemainShip    += _quantity;
        splitLine.QtyRemainReceive += _quantity;
        splitLine.update();
    }
    else
    {
        select maxOf(LineNum) from last
            where last.TransferId == original.TransferId;

        splitDim               = original.inventDim();
        if (_batchId)
        {
            splitDim.InventBatchId = _batchId;
        }
        if (_serialId)
        {
            splitDim.InventSerialId = _serialId;
        }

        splitLine.clear();
        splitLine.initValue();
        splitLine.initFromInventTransferTable(InventTransferTable::find(original.TransferId), NoYes::Yes);
        splitLine.ItemId = original.ItemId;
        splitLine.initFromInventTable(InventTable::find(splitLine.ItemId));
        splitLine.UnitId           = original.UnitId;
        splitLine.InventDimId      = InventDim::findOrCreate(splitDim).inventDimId;
        splitLine.QtyTransfer      = _quantity;
        splitLine.QtyRemainShip    = _quantity;
        splitLine.QtyRemainReceive = _quantity;
        splitLine.LineNum          = real2int(last.LineNum) + 1;
        splitLine.insert();
        _lineOfBatch.insert(_batchKey, splitLine.LineNum);

        splitRecId = splitLine.RecId;
        select forUpdate firstOnly splitLine
            where splitLine.RecId == splitRecId;
    }
    return splitLine;
}

/// <summary>
/// How much of a transfer line this posting has already moved onto lines of other batches
/// (splitForBatch) - still part of what the line had outstanding when the posting began.
/// </summary>
private static InventQty movedOff(Map _lineOfBatch, LineNum _lineNum, InventTransferId _transferId)
{
    MapEnumerator      enumerator = _lineOfBatch.getEnumerator();
    InventTransferLine splitLine;
    InventQty          moved;
    str                prefix = strFmt('%1|', _lineNum);

    while (enumerator.moveNext())
    {
        if (subStr(enumerator.currentKey(), 1, strLen(prefix)) == prefix)
        {
            select firstOnly QtyTransfer from splitLine
                where splitLine.TransferId == _transferId
                   && splitLine.LineNum    == enumerator.currentValue();
            moved += splitLine.QtyTransfer;
        }
    }
    return moved;
}

/// <summary>
/// Picks a transfer line the moment the worker scans it on Transfer - Ship, so its issue
/// transaction is Picked in D365FO before the shipment is posted (feedback 8b3daea2): a
/// positive Quantity picks that much from the bin, batch and serial scanned; a negative one
/// unpicks it again (the worker removed the line or lowered its quantity). The shipment
/// posting later skips lines sent with Picked. Runs now, not through HSMobileOpsPostQueue -
/// the worker is waiting on it - and leaves the line as it was when D365FO refuses.
/// </summary>
public HSMobileOpsPostResponse pickTransferLine(HSMobileOpsPostRequest _request)
{
    HSMobileOpsPostResponse response = new HSMobileOpsPostResponse();
    InventTransferLine      transferLine;
    HSMobileOpsPostLine     postLine;
    ListEnumerator          enumerator;
    InventDim               lineDim;
    List                    lines;
    InventQty               pickedBefore;
    boolean                 alreadyPicked;

    response.parmSuccess(false);
    if (!_request || !_request.parmDataAreaId() || !_request.parmSourceId())
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    lines = HSMobileOpsPostingService::parseLines(_request.parmLinesJson());
    if (!lines.elements())
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    changecompany (_request.parmDataAreaId())
    {
        str frozen = HSMobileOpsWarehouseFreeze::frozenMessage(HSMobileOpsPostingService::warehouseOf('TransferShipment', _request.parmSourceId()));
        if (frozen)
        {
            response.parmErrorCode('WAREHOUSE_FROZEN');
            response.parmMessage(frozen);
            return response;
        }
        try
        {
            ttsbegin;
            enumerator = lines.getEnumerator();
            while (enumerator.moveNext())
            {
                postLine = enumerator.current();
                select forupdate firstonly transferLine
                    where transferLine.TransferId == _request.parmSourceId()
                       && transferLine.LineNum    == postLine.parmLineNumber();
                if (!transferLine.RecId)
                {
                    throw error(strFmt('Line %1 is not on %2', postLine.parmLineNumber(), _request.parmSourceId()));
                }
                if (postLine.parmQuantity() > 0)
                {
                    // The line is not changed: the batch, serial and bin go on the picked
                    // inventory transactions only.
                    pickedBefore = HSMobileOpsPostingService::pickedQty(transferLine);
                    if (pickedBefore > 0 && HSMobileOpsPostingService::unpickedQty(transferLine) <= 0)
                    {
                        alreadyPicked = true;
                        throw error(strFmt('%1 on line %2 is all picked in D365FO already - confirm picking to ship it',
                            transferLine.ItemId, transferLine.LineNum));
                    }
                    HSMobileOpsPostingService::pickLine(transferLine, postLine, postLine.parmQuantity(), true);
                    // D365FO's pick does nothing - without an error - when there is no stock
                    // to pick from (negative physical inventory, BSP-TO-000000025: batch
                    // E0927 at -4 in AAC). Said so, rather than reported as picked.
                    if (HSMobileOpsPostingService::pickedQty(transferLine) - pickedBefore < postLine.parmQuantity())
                    {
                        throw error(strFmt('No stock of %1%2%3 in %4 to pick from - it is shipped from the order when the transfer is posted',
                            transferLine.ItemId,
                            postLine.parmBatchId() ? ' batch ' + postLine.parmBatchId() : '',
                            postLine.parmLocationId() ? ' in bin ' + postLine.parmLocationId() : '',
                            transferLine.inventDim().InventLocationId));
                    }
                }
                else if (postLine.parmQuantity() < 0)
                {
                    HSMobileOpsPostingService::unpickLine(transferLine, postLine, -postLine.parmQuantity());
                }
            }
            ttscommit;
            response.parmSuccess(true);
            response.parmDocumentNumber(_request.parmSourceId());
        }
        catch (Exception::Error)
        {
            // ALREADY_PICKED: the app counts the line as picked - it ships as it is.
            response.parmErrorCode(alreadyPicked ? 'ALREADY_PICKED' : 'NOT_PICKED');
            response.parmMessage(HSMobileOpsPostingService::lastError());
        }
        catch (Exception::Deadlock)
        {
            response.parmErrorCode('RETRY');
            response.parmMessage('D365FO was busy - try again');
        }
    }
    return response;
}

/// <summary>
/// How much of a transfer line's shipment is Picked in D365FO now.
/// </summary>
private static InventQty pickedQty(InventTransferLine _transferLine)
{
    InventTrans inventTrans;

    select sum(Qty) from inventTrans
        where inventTrans.InventTransOrigin == InventTransOrigin::findByInventTransId(_transferLine.InventTransId).RecId
           && inventTrans.StatusReceipt     == StatusReceipt::None
           && inventTrans.StatusIssue       == StatusIssue::Picked;

    return -inventTrans.Qty;
}

/// <summary>
/// How much of a transfer line's shipment is still open and not Picked in D365FO.
/// </summary>
private static InventQty unpickedQty(InventTransferLine _transferLine)
{
    InventTrans inventTrans;

    select sum(Qty) from inventTrans
        where inventTrans.InventTransOrigin == InventTransOrigin::findByInventTransId(_transferLine.InventTransId).RecId
           && inventTrans.StatusReceipt     == StatusReceipt::None
           && inventTrans.StatusIssue       >  StatusIssue::Picked;

    return -inventTrans.Qty;
}

/// <summary>
/// Takes _quantity off what is picked on a transfer line's shipment - of the batch, serials
/// and bin given, when given - back to its earlier status, as D365FO's Pick form does with a
/// negative quantity.
/// </summary>
private static void unpickLine(InventTransferLine _transferLine, HSMobileOpsPostLine _postLine, InventQty _quantity)
{
    InventTransOriginId  originId = InventTransOrigin::findByInventTransId(_transferLine.InventTransId).RecId;
    InventTrans          inventTrans;
    InventDim            dim;
    TmpInventTransWMS    tmpInventTransWMS;
    InventTransWMS_Pick  pick;
    Query                query;
    QueryBuildDataSource qbds;
    List                 serials = _postLine.parmSerialIds();
    Set                  wanted  = new Set(Types::String);
    ListEnumerator       serialEnumerator;
    InventQty            remaining = _quantity;
    InventQty            qty;

    if (serials)
    {
        serialEnumerator = serials.getEnumerator();
        while (serialEnumerator.moveNext())
        {
            wanted.add(serialEnumerator.current());
        }
    }

    query = new Query();
    qbds  = query.addDataSource(tableNum(InventTrans));
    qbds.addRange(fieldNum(InventTrans, StatusReceipt)).value(SysQuery::value(StatusReceipt::None));
    qbds.addRange(fieldNum(InventTrans, StatusIssue)).value(SysQuery::value(StatusIssue::Picked));
    qbds.addRange(fieldNum(InventTrans, InventTransOrigin)).value(SysQuery::value(originId));
    pick = InventTransWMS_Pick::newStandard(tmpInventTransWMS, query);

    while select inventTrans
        where inventTrans.InventTransOrigin == originId
           && inventTrans.StatusReceipt     == StatusReceipt::None
           && inventTrans.StatusIssue       == StatusIssue::Picked
    {
        if (remaining <= 0)
        {
            break;
        }
        dim = inventTrans.inventDim();
        if ((_postLine.parmBatchId() && dim.InventBatchId != _postLine.parmBatchId())
         || (wanted.elements() && !wanted.in(dim.InventSerialId))
         || (_postLine.parmLocationId() && dim.wMSLocationId && dim.wMSLocationId != _postLine.parmLocationId()))
        {
            continue;
        }
        qty = min(remaining, -inventTrans.Qty);
        if (qty <= 0)
        {
            continue;
        }
        // A negative quantity on a picked issue: an unpick.
        HSMobileOpsPostingService::addPick(pick, tmpInventTransWMS, inventTrans, dim, -qty);
        remaining -= qty;
    }
    if (remaining > 0)
    {
        throw error(strFmt('Only %1 of %2 is picked on line %3 to unpick',
            _quantity - remaining, _quantity, _transferLine.LineNum));
    }
    if (!pick.updateInvent())
    {
        throw error(strFmt('D365FO did not unpick %1 on line %2', _transferLine.ItemId, _transferLine.LineNum));
    }
}

/// <summary>
/// Picks a transfer line's shipment from the batch and serials the worker scanned - the
/// issue-side twin of registerLine, with InventTransWMS_Pick in place of
/// InventTransWMS_Register. Lines with neither are left to D365FO's own choice, as before.
///
/// The ship flow asks the bin first (feedback 46890e91): each pick takes stock from that bin
/// when one was scanned and the item tracks location, else from wherever physical stock holds
/// that batch or serial in the shipping warehouse - with its location and inventory status.
/// With serial number control each serial is one unit; without it the single serial covers
/// the line. A line with only a bin scanned is picked from that bin too.
/// </summary>
private static void pickLine(InventTransferLine _transferLine, HSMobileOpsPostLine _postLine, InventQty _quantity,
    boolean _always = false)
{
    InventTransOriginId  originId = InventTransOrigin::findByInventTransId(_transferLine.InventTransId).RecId;
    InventTrans          inventTrans;
    InventDim            lineDim;
    InventDim            pickDim;
    TmpInventTransWMS    tmpInventTransWMS;
    InventTransWMS_Pick  pick;
    Query                query;
    QueryBuildDataSource qbds;
    List                 serials = _postLine.parmSerialIds();
    ListEnumerator       serialEnumerator;
    boolean              perUnit;
    WMSLocationId        bin = _postLine.parmLocationId();

    if (bin && !InventDimGroupSetup::newItemId(_transferLine.ItemId).isDimensionActive(fieldNum(InventDim, wMSLocationId)))
    {
        bin = '';
    }
    // At posting a line with neither is left to D365FO's own choice; picked when scanned
    // (_always) it is picked too, from wherever its stock is.
    if (!_always && !_postLine.parmBatchId() && !(serials && serials.elements()) && !bin)
    {
        return;
    }

    // The shipment's issue transaction - the line's origin also holds the transit receipt.
    select firstonly inventTrans
        where inventTrans.InventTransOrigin == originId
           && inventTrans.StatusReceipt     == StatusReceipt::None
           && inventTrans.StatusIssue       >= StatusIssue::Picked
           && inventTrans.StatusIssue       <= StatusIssue::OnOrder;
    if (!inventTrans.RecId)
    {
        return;
    }

    lineDim = inventTrans.inventDim();
    if (_postLine.parmBatchId())
    {
        lineDim.InventBatchId = _postLine.parmBatchId();
    }

    // The same query D365FO's own Pick form (InventTransPick) hands InventTransWMS_Pick.
    query = new Query();
    qbds  = query.addDataSource(tableNum(InventTrans));
    qbds.addRange(fieldNum(InventTrans, StatusReceipt)).value(SysQuery::value(StatusReceipt::None));
    qbds.addRange(fieldNum(InventTrans, StatusIssue)).value(SysQuery::range(StatusIssue::Picked, StatusIssue::OnOrder));
    qbds.addRange(fieldNum(InventTrans, InventTransOrigin)).value(SysQuery::value(originId));
    pick = InventTransWMS_Pick::newStandard(tmpInventTransWMS, query);

    if (serials && serials.elements())
    {
        perUnit = HSMobileOpsDimensionRules::serialPerUnit(InventDimGroupSetup::newItemId(inventTrans.ItemId));
        serialEnumerator = serials.getEnumerator();
        while (serialEnumerator.moveNext())
        {
            lineDim.InventSerialId = serialEnumerator.current();
            pickDim = HSMobileOpsPostingService::stockDim(inventTrans.ItemId, lineDim, bin);
            HSMobileOpsPostingService::addPick(pick, tmpInventTransWMS, inventTrans, pickDim, perUnit ? 1 : _quantity);
        }
    }
    else
    {
        pickDim = HSMobileOpsPostingService::stockDim(inventTrans.ItemId, lineDim, bin);
        HSMobileOpsPostingService::addPick(pick, tmpInventTransWMS, inventTrans, pickDim, _quantity);
    }
    if (!pick.updateInvent())
    {
        throw error(strFmt('D365FO did not pick %1 on line %2', _transferLine.ItemId, _transferLine.LineNum));
    }
}

/// <summary>
/// Why a scanned batch cannot be received on a transfer line, or '' when it can: it must be
/// a batch shipped on the line, in no more than is still to receive of it. Without this the
/// receipt registers the scanned batch whatever left the source warehouse - BSP-TO-000000020
/// shipped 4S2MK and was received as 3S6NC (feedback 0c8c65da), and with physical negative
/// inventory nothing else in posting refuses it.
///
/// The app checks the same list when the batch is scanned; this catches postings from an
/// app without that check, or queued before the shipment changed. A line shipped without
/// batches has no list, and is not checked. Earlier scans of this posting are already
/// registered (registerTransferReceipt), so the list has them deducted.
/// </summary>
private static str unshippedBatch(InventTransferLine _transferLine, InventBatchId _batchId, InventQty _quantity)
{
    List                        shipped = HSMobileOpsTransferService::shippedBatchesOf(
                                    _transferLine.InventTransId, _transferLine.InventTransIdReceive);
    ListEnumerator              enumerator = shipped.getEnumerator();
    HSMobileOpsTransferBatchRow row;
    str                         list;

    if (!shipped.elements())
    {
        return '';
    }
    while (enumerator.moveNext())
    {
        row = enumerator.current();
        if (row.parmBatchId() == _batchId)
        {
            return _quantity > row.parmQty()
                ? strFmt('Line %1: only %2 of batch %3 is left to receive', _transferLine.LineNum, row.parmQty(), _batchId)
                : '';
        }
        list += (list ? ', ' : '') + strFmt('%1 (%2)', row.parmBatchId(), row.parmQty());
    }
    return strFmt('Line %1: batch %2 was not shipped on %3. Shipped: %4',
        _transferLine.LineNum, _batchId, _transferLine.TransferId, list);
}

/// <summary>
/// Registers what the worker received of a transfer line at the put-away location, before
/// the receipt is posted. Items whose model group requires registration otherwise refuse the
/// receipt ("cannot be received because inventory transactions with status Registered are
/// insufficient"); for the rest it is the same registration a receiving clerk does in
/// D365FO. The batch and serial come over from the shipment on each in-transit transaction -
/// one per shipped batch or serial - so each is registered as it stands, with the location
/// (and a default inventory status where the item uses one) added, and the scanned batch when
/// one was scanned without serials.
///
/// Only [_quantity] is registered, so a partial receipt leaves the rest in transit: the
/// scanned serials when the shipment carries serials, otherwise the scanned batch first and
/// then whatever else is in transit. A transaction larger than what is left is split.
/// </summary>
private static void registerTransferReceipt(InventTransferLine _transferLine, HSMobileOpsPostLine _postLine, InventQty _quantity)
{
    InventTransOriginId     originId = InventTransOrigin::findByInventTransId(_transferLine.InventTransIdReceive).RecId;
    InventTrans             inventTrans;
    InventDim               inventDim;
    TmpInventTransWMS       tmpInventTransWMS;
    InventTransWMS_Register register;
    boolean                 statusActive = InventDimGroupSetup::newItemId(_transferLine.ItemId)
                                .isDimensionActive(fieldNum(InventDim, InventStatusId));
    WMSLocationId           location = _postLine.parmLocationId();
    InventBatchId           batchId  = _postLine.parmBatchId();
    List                    serials  = _postLine.parmSerialIds();
    Set                     scanned  = new Set(Types::String);
    ListEnumerator          serialEnumerator;
    boolean                 shippedWithSerials;
    container               matching;
    container               others;
    container               recIds;
    InventQty               remaining = _quantity;
    InventQty               qty;
    int                     i;

    if (serials)
    {
        serialEnumerator = serials.getEnumerator();
        while (serialEnumerator.moveNext())
        {
            scanned.add(serialEnumerator.current());
        }
    }

    // Collected first: registering splits and updates these same rows.
    while select RecId, InventDimId from inventTrans
        where inventTrans.InventTransOrigin == originId
           && inventTrans.StatusIssue       == StatusIssue::None
           && inventTrans.StatusReceipt     == StatusReceipt::Ordered
    {
        inventDim = InventDim::find(inventTrans.InventDimId);
        if (inventDim.InventSerialId)
        {
            shippedWithSerials = true;
        }

        if ((scanned.elements() && scanned.in(inventDim.InventSerialId))
         || (!scanned.elements() && batchId && inventDim.InventBatchId == batchId))
        {
            matching += inventTrans.RecId;
        }
        else
        {
            others += inventTrans.RecId;
        }
    }

    // Scanned serials that were shipped: exactly those. Otherwise by quantity, the scanned
    // batch first.
    recIds = (scanned.elements() && shippedWithSerials) ? matching : matching + others;

    for (i = 1; i <= conLen(recIds) && remaining > 0; i++)
    {
        select forupdate firstonly inventTrans where inventTrans.RecId == conPeek(recIds, i);
        qty = min(remaining, inventTrans.Qty);
        if (qty <= 0)
        {
            continue;
        }

        inventDim = inventTrans.inventDim();
        if (location)
        {
            inventDim.wMSLocationId = location;
        }
        // The batch the worker scanned, checked on the handheld against what left the source
        // warehouse (ShippedBatches). The in-transit transaction can carry another one: on
        // BSP-TO-000000017 0.58 left as 4S2MK but was in transit as 3S6NC, and receiving it
        // as 3S6NC failed with "Total received quantity exceeds shipped quantity".
        if (batchId && !scanned.elements())
        {
            inventDim.InventBatchId = batchId;
        }
        if (statusActive && !inventDim.InventStatusId && inventDim.wMSLocationId)
        {
            inventDim.InventStatusId = HSMobileOpsPostingService::defaultStatus(inventDim.InventLocationId);
        }
        inventDim = InventDim::findOrCreate(inventDim);

        register = InventTransWMS_Register::newStandard(tmpInventTransWMS);
        // As in registerLine: the registration line takes its dimension from the
        // transaction it is built from, so the put-away location goes on that first.
        inventTrans.InventDimId = inventDim.InventDimId;
        tmpInventTransWMS.clear();
        tmpInventTransWMS.initFromInventTrans(inventTrans);
        tmpInventTransWMS.ItemId    = inventTrans.ItemId;
        tmpInventTransWMS.InventQty = qty;
        tmpInventTransWMS.insert();
        register.writeTmpInventTransWMS(tmpInventTransWMS, inventTrans, inventDim);
        register.updateInvent(inventTrans);

        remaining -= qty;
    }
}

private static InventSerialId firstSerial(List _serials)
{
    ListEnumerator enumerator = _serials.getEnumerator();
    return enumerator.moveNext() ? enumerator.current() : '';
}

private static void addPick(InventTransWMS_Pick _pick, TmpInventTransWMS _tmp, InventTrans _inventTrans,
    InventDim _pickDim, InventQty _quantity)
{
    TmpInventTransWMS line;

    // Built the way InventTransWMS_Pick builds its own lines, and handed over uninserted: the
    // class records it then (setSelectedQty). Inserted first, as this did, the class took it
    // for an edit of an existing line with nothing changed - and picked nothing, silently.
    line.initFromInventTrans(_inventTrans);
    line.initFromInventTransOrigin(_inventTrans.inventTransOrigin());
    // In the class's own sign: the quantity to pick, negative to unpick.
    line.InventQty   = _quantity;
    // Where it is picked from: the bin, batch and status of the stock taken.
    line.InventDimId = _pickDim.InventDimId;
    if (!_pick.writeTmpInventTransWMS(line))
    {
        throw error(strFmt('D365FO would not %1 %2 of %3', _quantity < 0 ? 'unpick' : 'pick', abs(_quantity), _inventTrans.ItemId));
    }
}

/// <summary>
/// The full dimension of physical stock matching _wanted's warehouse, product dimensions,
/// batch and serial - so its location and status come from where the goods actually are.
/// _wanted itself when nothing matches, and D365FO then says what is missing.
/// </summary>
private static InventDim stockDim(ItemId _itemId, InventDim _wanted, WMSLocationId _bin = '')
{
    InventSum inventSum;
    InventDim stock;

    select firstonly inventSum
        where inventSum.ItemId         == _itemId
           && inventSum.Closed         == NoYes::No
           && inventSum.PhysicalInvent >  0
        join stock
            where stock.inventDimId      == inventSum.InventDimId
               && stock.InventLocationId == _wanted.InventLocationId
               && stock.ConfigId         == _wanted.ConfigId
               && stock.InventSizeId     == _wanted.InventSizeId
               && stock.InventColorId    == _wanted.InventColorId
               && stock.InventStyleId    == _wanted.InventStyleId
               && (!_wanted.InventBatchId  || stock.InventBatchId  == _wanted.InventBatchId)
               && (!_wanted.InventSerialId || stock.InventSerialId == _wanted.InventSerialId)
               && (!_bin                   || stock.wMSLocationId  == _bin);

    if (!stock.RecId && _bin)
    {
        _wanted.wMSLocationId = _bin;
    }
    return stock.RecId ? stock : InventDim::findOrCreate(_wanted);
}

/// <summary>
/// Checks the request is complete enough to post, returning an error code or an empty string.
///
/// The serial count check earns its place: a serial identifies exactly one physical unit, so
/// three serials against a quantity of five is not a rounding difference, it is two units
/// nobody can ever trace. Refusing beats posting something that cannot be unpicked.
///
/// One per unit only where the item's tracking group has serial number control. Without it
/// D365FO itself lets one serial cover the line, and the device asks for exactly one
/// (SerialPerUnit on the line) - requiring one per unit here refused every such receipt.
/// </summary>
private static str validate(HSMobileOpsPostRequest _request, boolean _referenceRequired)
{
    HSMobileOpsPostLine postLine;
    List                 lines;
    ListEnumerator      enumerator;
    boolean             perUnit;

    if (!_request
     || !_request.parmDataAreaId()
     || !_request.parmIdempotencyKey()
     || !_request.parmSourceId()
     || !_request.parmLinesJson()
     || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        return 'INVALID_REQUEST';
    }

    // Kept as a parameter, but no caller passes true any more - see the note at
    // postProductReceipt's own validate() call. A reference is accepted when sent and
    // ignored when not.
    if (_referenceRequired && !_request.parmReference())
    {
        return 'INVALID_REQUEST';
    }

    lines = HSMobileOpsPostingService::parseLines(_request.parmLinesJson());
    if (!lines || !lines.elements())
    {
        return 'INVALID_REQUEST';
    }

    enumerator = lines.getEnumerator();
    while (enumerator.moveNext())
    {
        postLine = enumerator.current();

        if (!postLine.parmItemId() || postLine.parmQuantity() <= 0)
        {
            return 'INVALID_REQUEST';
        }

        if (postLine.parmSerialIds() && postLine.parmSerialIds().elements())
        {
            changecompany (_request.parmDataAreaId())
            {
                perUnit = HSMobileOpsDimensionRules::serialPerUnit(InventDimGroupSetup::newItemId(postLine.parmItemId()));
            }
            if (perUnit ? postLine.parmSerialIds().elements() != postLine.parmQuantity()
                        : postLine.parmSerialIds().elements() != 1)
            {
                return 'SERIAL_COUNT';
            }
        }
    }

    return '';
}

/// <summary>
/// The quantity of a purchase line still Ordered in InventTrans, in the purchase unit - what
/// can still be registered. The same reading as HSMobileOpsReceivingService.orderedQtyByLine.
/// </summary>
private static PurchQty orderedQty(PurchLine _purchLine)
{
    InventQty inventQty = HSMobileOpsPostingService::orderedInventQty(_purchLine);

    // InventTrans is in the inventory unit; the line and the request are in the purchase unit.
    // QtyOrdered is the line in the inventory unit, PurchQty in the purchase unit.
    if (_purchLine.QtyOrdered && _purchLine.QtyOrdered != _purchLine.PurchQty)
    {
        return inventQty * _purchLine.PurchQty / _purchLine.QtyOrdered;
    }
    return inventQty;
}

/// <summary>
/// The quantity of a purchase line still Ordered in InventTrans, in the inventory unit.
/// </summary>
private static InventQty orderedInventQty(PurchLine _purchLine)
{
    InventTrans        inventTrans;
    InventTransOrigin  inventTransOrigin;

    select sum(Qty) from inventTrans
        where inventTrans.StatusReceipt == StatusReceipt::Ordered
        exists join inventTransOrigin
            where inventTransOrigin.RecId         == inventTrans.InventTransOrigin
               && inventTransOrigin.InventTransId == _purchLine.InventTransId;

    return inventTrans.Qty;
}

/// <summary>
/// A purchase-unit quantity in the inventory unit, which is what registration takes: 5 Pack
/// at 20 pieces a pack is 100. Handed over unconverted it registered 5 pieces, and the GRN
/// then failed with "Physical remaining quantity ... must be other than zero" - or, without
/// a GRN, booked the wrong stock with no message (BSP-PO-000161720 line 471, 6 Nov 2026).
/// All that is left converts to exactly what is left, so rounding leaves no remainder.
/// </summary>
private static InventQty inventQtyOf(PurchLine _purchLine, PurchQty _quantity, PurchQty _available)
{
    if (!_purchLine.PurchQty || _purchLine.QtyOrdered == _purchLine.PurchQty)
    {
        return _quantity;
    }
    if (abs(_quantity - _available) < 0.000001)
    {
        return HSMobileOpsPostingService::orderedInventQty(_purchLine);
    }
    return _quantity * _purchLine.QtyOrdered / _purchLine.PurchQty;
}

/// <summary>
/// The request's lines, off the wire. See HSMobileOpsPostRequest.parmLinesJson for why this
/// is a hand-parsed JSON string rather than a bound List of HSMobileOpsPostLine.
///
/// Newtonsoft.Json.Linq is used directly rather than through a higher-level X++ JSON helper -
/// it is already proven present and loaded on this exact server, because it is what named
/// itself in the cast exception this whole change exists to route around. An empty or
/// unparseable string returns an empty list rather than throwing; callers already treat an
/// empty list of lines as INVALID_REQUEST, which is the right answer for malformed input too.
///
/// Public rather than the private this started as - HSMobileOpsReceivingService now reuses it
/// too, to read back a Pending row's own LinesJson when computing how much of a purchase
/// order line is already staged (see HSMobileOpsReceivingService::stagedQtyByLine). One parser
/// for the one JSON shape both classes read, not two that can drift apart.
/// </summary>
public static List parseLines(str _linesJson)
{
    List                          result = new List(Types::Class);
    System.Object                 parsedObj;
    Newtonsoft.Json.Linq.JArray   jArray;
    Newtonsoft.Json.Linq.JObject  jLine;
    Newtonsoft.Json.Linq.JToken   serialsToken;
    Newtonsoft.Json.Linq.JArray   jSerials;
    HSMobileOpsPostLine           postLine;
    List                          serialIds;
    int                           lineCount;
    int                           serialCount;
    int                           i;
    int                           j;

    if (!_linesJson)
    {
        return result;
    }

    try
    {
        parsedObj = Newtonsoft.Json.Linq.JArray::Parse(_linesJson);
    }
    catch (Exception::CLRError)
    {
        return result;
    }

    jArray = parsedObj;
    if (jArray == null)
    {
        return result;
    }

    lineCount = jArray.get_Count();

    for (i = 0; i < lineCount; i++)
    {
        jLine = jArray.get_Item(i);
        if (jLine == null)
        {
            continue;
        }

        postLine = new HSMobileOpsPostLine();
        postLine.parmLineNumber(HSMobileOpsPostingService::jsonNum(jLine, 'LineNumber'));
        postLine.parmItemId(HSMobileOpsPostingService::jsonStr(jLine, 'ItemId'));
        postLine.parmQuantity(HSMobileOpsPostingService::jsonNum(jLine, 'Quantity'));
        postLine.parmUnitId(HSMobileOpsPostingService::jsonStr(jLine, 'UnitId'));
        postLine.parmSiteId(HSMobileOpsPostingService::jsonStr(jLine, 'SiteId'));
        postLine.parmWarehouseId(HSMobileOpsPostingService::jsonStr(jLine, 'WarehouseId'));
        postLine.parmLocationId(HSMobileOpsPostingService::jsonStr(jLine, 'LocationId'));
        postLine.parmBatchId(HSMobileOpsPostingService::jsonStr(jLine, 'BatchId'));
        postLine.parmBatchManufacturingDate(
            HSMobileOpsPostingService::jsonStr(jLine, 'BatchManufacturingDate'));
        postLine.parmBatchExpiryDate(
            HSMobileOpsPostingService::jsonStr(jLine, 'BatchExpiryDate'));

        serialIds    = new List(Types::String);
        serialsToken = jLine.get_Item('SerialIds');
        if (serialsToken != null)
        {
            jSerials = serialsToken;
            if (jSerials != null)
            {
                serialCount = jSerials.get_Count();
                for (j = 0; j < serialCount; j++)
                {
                    serialIds.addEnd(jSerials.get_Item(j).ToString());
                }
            }
        }
        postLine.parmSerialIds(serialIds);
        postLine.parmPicked(strLwr(HSMobileOpsPostingService::jsonStr(jLine, 'Picked')) == 'true');

        result.addEnd(postLine);
    }

    return result;
}

/// <summary>
/// One property of a parsed JSON object, as a string - '' when absent rather than null, so
/// callers can keep using the same blank-means-not-set checks used everywhere else here.
/// </summary>
private static str jsonStr(Newtonsoft.Json.Linq.JObject _obj, str _property)
{
    Newtonsoft.Json.Linq.JToken token;

    if (_obj == null)
    {
        return '';
    }

    token = _obj.get_Item(_property);
    if (token == null)
    {
        return '';
    }

    return token.ToString();
}

/// <summary>
/// One property of a parsed JSON object, as a number - 0 when absent or not a number.
/// </summary>
private static real jsonNum(Newtonsoft.Json.Linq.JObject _obj, str _property)
{
    str value = HSMobileOpsPostingService::jsonStr(_obj, _property);

    if (!value)
    {
        return 0;
    }

    return str2num(value);
}

/// <summary>
/// Records the posting against its idempotency key.
///
/// Called inside the posting's own transaction, deliberately. The unique index means a
/// concurrent retry that got there first makes this insert fail, which rolls the posting back
/// with it - so a duplicate is impossible rather than merely unlikely. Checking first and
/// inserting afterwards would leave a window where two retries both find nothing and both post.
/// </summary>
private static void writeLog(
    HSMobileOpsPostRequest _request, str _documentType, str _documentNumber)
{
    HSMobileOpsPostLog postLog;

    postLog.clear();
    postLog.IdempotencyKey   = _request.parmIdempotencyKey();
    postLog.DocumentType     = _documentType;
    postLog.SourceId         = _request.parmSourceId();
    postLog.DocumentNumber   = _documentNumber;
    postLog.PostedByUserName = _request.parmUserName();
    postLog.PersonnelNumber  = _request.parmPersonnelNumber();
    postLog.DeviceId         = _request.parmDeviceId();
    postLog.PostedUtc        = DateTimeUtil::utcNow();
    postLog.insert();
}

/// <summary>
/// The answer to a request that has already been posted.
///
/// Success, not failure. The client's retry did exactly what it was supposed to, and the work
/// landed once - so it clears its queue entry knowing the receipt exists, and the operator is
/// not told a second one was created when it was not.
/// </summary>
private static HSMobileOpsPostResponse replayOf(
    HSMobileOpsPostResponse _response, HSMobileOpsPostLog _existing)
{
    _response.parmSuccess(true);
    _response.parmAlreadyPosted(true);
    _response.parmDocumentNumber(_existing.DocumentNumber);
    _response.parmMessage(strFmt(
        'Already posted as %1 at %2',
        _existing.DocumentNumber, DateTimeUtil::toStr(_existing.PostedUtc)));

    return _response;
}

/// <summary>
/// D365FO's own message for the failure that just occurred.
///
/// Passed through rather than summarised. "Posting failed" tells a warehouse supervisor
/// nothing; "the period is closed" or "item is stopped" tells them exactly who to call.
/// </summary>
private static str lastError(int _fromLine = 0)
{
    // From _fromLine on: run from a form, the infolog still holds what earlier actions logged.
    SysInfologEnumerator enumerator = SysInfologEnumerator::newData(infolog.copy(_fromLine + 1, infologLine()));
    str                  message;

    // Every Error line, joined - a DB failure logs the operation, then "The SQL database
    // has issued an error", then often a lock/session line, and keeping only the last one
    // (as this did) threw away the part that actually says what went wrong.
    // Warnings too: validation (checkFailed) logs the actual reason as a warning, and the
    // error after it is only "Update has been canceled" - on its own, nothing to act on.
    while (enumerator.moveNext())
    {
        if (enumerator.currentException() == Exception::Error
         || enumerator.currentException() == Exception::Warning)
        {
            message += (message ? ' | ' : '') + enumerator.currentMessage();
        }
    }

    return message ? message : 'D365FO refused the posting without a message';
}
